/****************************************************************************
 * apps/examples/deskmate/src/hal/dm_display.c
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * Display half of the DeskMate HAL: see dm_display.h for the two backends.
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <unistd.h>

#include <lvgl/lvgl.h>

#include "dm_config.h"
#include "dm_log.h"
#include "hal/dm_display.h"

#if DM_DISPLAY_FBDEV
#  include <nuttx/video/fb.h>
#endif

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct dm_display_metrics_s g_metrics;
static lv_display_t *g_disp;
static bool g_created;

#if DM_DISPLAY_FBDEV
static int g_fb_fd = -1;
static struct fb_planeinfo_s g_plane;
#endif

#if DM_DISPLAY_MEM
static uint8_t *g_mem_pixels;
static size_t g_mem_size;

/* With a full-screen render buffer the draw buffer *is* the frame: the flush
 * callback only has to acknowledge it.
 */

static void dm_flush_cb(lv_display_t *disp, const lv_area_t *area,
                        uint8_t *px_map)
{
  (void)area;
  (void)px_map;
  lv_display_flush_ready(disp);
}
#endif

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/* Create the parent directory of a snapshot path, best effort. */

static void dm_makedirs_for(const char *path)
{
  char tmp[128];
  char *slash;
  size_t len;

  len = strlen(path);
  if (len == 0 || len >= sizeof(tmp))
    {
      return;
    }

  strlcpy(tmp, path, sizeof(tmp));
  slash = strrchr(tmp, '/');
  if (slash == NULL || slash == tmp)
    {
      return;
    }

  *slash = '\0';

  for (char *p = tmp + 1; *p != '\0'; p++)
    {
      if (*p == '/')
        {
          *p = '\0';
          (void)mkdir(tmp, 0777);
          *p = '/';
        }
    }

  (void)mkdir(tmp, 0777);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int dm_display_create(void)
{
  lv_nuttx_dsc_t info;
  lv_nuttx_result_t result;

  if (g_created)
    {
      return 0;
    }

  memset(&g_metrics, 0, sizeof(g_metrics));
  memset(&result, 0, sizeof(result));

  lv_nuttx_dsc_init(&info);

#if DM_DISPLAY_FBDEV
  {
    struct fb_videoinfo_s vinfo;

    g_fb_fd = open(DM_FB_PATH, O_RDWR | O_CLOEXEC);
    if (g_fb_fd < 0)
      {
        DM_ERR("cannot open framebuffer %s: %d", DM_FB_PATH, errno);
        return -errno;
      }

    memset(&vinfo, 0, sizeof(vinfo));
    memset(&g_plane, 0, sizeof(g_plane));

    if (ioctl(g_fb_fd, FBIOGET_VIDEOINFO, (unsigned long)&vinfo) < 0 ||
        ioctl(g_fb_fd, FBIOGET_PLANEINFO, (unsigned long)&g_plane) < 0)
      {
        DM_ERR("FBIOGET_* failed on %s: %d", DM_FB_PATH, errno);
        close(g_fb_fd);
        g_fb_fd = -1;
        return -errno;
      }

    g_metrics.width       = vinfo.xres;
    g_metrics.height      = vinfo.yres;
    g_metrics.bpp         = g_plane.bpp;
    g_metrics.stride      = g_plane.stride;
    g_metrics.memory      = false;
    g_metrics.pixels      = (uint8_t *)g_plane.fbmem;
    g_metrics.pixels_size = (size_t)g_plane.stride * g_metrics.height;
    g_metrics.backend     = "fbdev";

    info.fb_path    = DM_FB_PATH;
    info.input_path = DM_INPUT_PATH;
#if defined(CONFIG_UINPUT_TOUCH)
    info.utouch_path = NULL;
#endif

    lv_nuttx_init(&info, &result);

    if (result.disp == NULL)
      {
        DM_ERR("LVGL could not attach to %s", DM_FB_PATH);
        close(g_fb_fd);
        g_fb_fd = -1;
        return -ENODEV;
      }

    g_disp = result.disp;

    DM_LOG("display: %s %dx%d bpp=%d stride=%d", g_metrics.backend,
           g_metrics.width, g_metrics.height, g_metrics.bpp,
           g_metrics.stride);
  }
#else /* DM_DISPLAY_MEM */
  {
    int width  = DM_MEM_WIDTH;
    int height = DM_MEM_HEIGHT;
    size_t stride = (size_t)width * 2;      /* RGB565 */

    /* Initialise the LVGL NuttX entry for its tick and cache setup, but do
     * not let it look for a framebuffer or a touchscreen device: there is
     * neither in a headless run.
     */

    info.fb_path    = NULL;
    info.input_path = NULL;
#if defined(CONFIG_UINPUT_TOUCH)
    info.utouch_path = NULL;
#endif
#if defined(CONFIG_LV_USE_NUTTX_MOUSE)
    info.mouse_path = NULL;
#endif

    lv_nuttx_init(&info, &result);

    g_mem_size = stride * height;
    if (g_mem_size > DM_SNAP_MAX_BYTES)
      {
        DM_ERR("in-memory display too large: %u bytes", (unsigned)g_mem_size);
        return -E2BIG;
      }

    g_mem_pixels = malloc(g_mem_size);
    if (g_mem_pixels == NULL)
      {
        DM_ERR("no memory for a %ux%u RGB565 frame",
               (unsigned)width, (unsigned)height);
        return -ENOMEM;
      }

    memset(g_mem_pixels, 0, g_mem_size);

    g_disp = lv_display_create(width, height);
    if (g_disp == NULL)
      {
        DM_ERR("lv_display_create failed");
        free(g_mem_pixels);
        g_mem_pixels = NULL;
        return -ENOMEM;
      }

    lv_display_set_color_format(g_disp, LV_COLOR_FORMAT_RGB565);
    lv_display_set_flush_cb(g_disp, dm_flush_cb);
    lv_display_set_buffers(g_disp, g_mem_pixels, NULL, (uint32_t)g_mem_size,
                           LV_DISPLAY_RENDER_MODE_FULL);

    g_metrics.width       = width;
    g_metrics.height      = height;
    g_metrics.bpp         = 16;
    g_metrics.stride      = (int)stride;
    g_metrics.memory      = true;
    g_metrics.pixels      = g_mem_pixels;
    g_metrics.pixels_size = g_mem_size;
    g_metrics.backend     = "mem";

    DM_LOG("display: %s %dx%d bpp=%d stride=%d (headless)",
           g_metrics.backend, g_metrics.width, g_metrics.height,
           g_metrics.bpp, g_metrics.stride);
  }
#endif

  g_created = true;
  return 0;
}

const struct dm_display_metrics_s *dm_display_metrics(void)
{
  return g_created ? &g_metrics : NULL;
}

void *dm_display_lv(void)
{
  return g_disp;
}

int dm_display_snapshot(const char *path)
{
  FILE *fp;
  size_t written;
  char meta[128];
  int meta_len;

  if (!g_created || path == NULL)
    {
      return -EINVAL;
    }

  if (g_metrics.pixels == NULL || g_metrics.pixels_size == 0)
    {
      return -ENODEV;
    }

  if (g_metrics.pixels_size > DM_SNAP_MAX_BYTES)
    {
      return -E2BIG;
    }

  dm_makedirs_for(path);

  fp = fopen(path, "wb");
  if (fp == NULL)
    {
      DM_ERR("cannot create snapshot %s: %d", path, errno);
      return -errno;
    }

  written = fwrite(g_metrics.pixels, 1, g_metrics.pixels_size, fp);
  fclose(fp);

  if (written != g_metrics.pixels_size)
    {
      DM_ERR("short snapshot write: %u/%u", (unsigned)written,
             (unsigned)g_metrics.pixels_size);
      return -EIO;
    }

  meta_len = snprintf(meta, sizeof(meta),
                      "%s.txt", path);
  if (meta_len > 0 && (size_t)meta_len < sizeof(meta))
    {
      fp = fopen(meta, "w");
      if (fp != NULL)
        {
          fprintf(fp, "width=%d\nheight=%d\nbpp=%d\nstride=%d\nbackend=%s\n",
                  g_metrics.width, g_metrics.height, g_metrics.bpp,
                  g_metrics.stride, g_metrics.backend);
          fclose(fp);
        }
    }

  DM_LOG("snapshot: %s (%u bytes, %dx%d %dbpp %s)", path,
         (unsigned)g_metrics.pixels_size, g_metrics.width, g_metrics.height,
         g_metrics.bpp, g_metrics.backend);

  return (int)g_metrics.pixels_size;
}

int dm_display_stats(struct dm_display_stats_s *stats)
{
  const uint8_t *pixels;
  int width;
  int height;
  int stride;
  int bpp;
  int step;
  int samples = 0;
  int max_grad = 0;
  int best_count = 0;
  int i;

  static uint16_t colours[256];
  static int counts[256];
  int distinct = 0;

  if (stats == NULL || !g_created || g_metrics.pixels == NULL)
    {
      return -EINVAL;
    }

  pixels = g_metrics.pixels;
  width  = g_metrics.width;
  height = g_metrics.height;
  stride = g_metrics.stride;
  bpp    = g_metrics.bpp;

  memset(stats, 0, sizeof(*stats));

  /* Sample every 7th pixel in both directions: cheap even on the board and
   * plenty to tell a drawn UI from a blank or noisy panel.
   */

  step = 7;

  for (int y = 0; y < height; y += step)
    {
      const uint8_t *row = pixels + (size_t)y * stride;

      for (int x = 0; x < width; x += step)
        {
          uint16_t colour;
          int prev = -1;

          if (bpp == 16)
            {
              const uint16_t *p16 = (const uint16_t *)row;
              colour = p16[x];
            }
          else if (bpp == 32)
            {
              const uint32_t *p32 = (const uint32_t *)row;
              colour = (uint16_t)(p32[x] & 0xffff);
            }
          else
            {
              colour = row[x];
            }

          samples++;

          /* Horizontal neighbour gradient, only while the previous sample is
           * still the immediate neighbour.
           */

          if (x >= step && bpp == 16)
            {
              const uint16_t *p16 = (const uint16_t *)row;
              prev = (int)p16[x - step];
            }

          if (prev >= 0)
            {
              int d = (int)colour - prev;
              if (d < 0)
                {
                  d = -d;
                }

              if (d > max_grad)
                {
                  max_grad = d;
                }
            }

          /* Colour histogram, saturating at 256 buckets. */

          for (i = 0; i < distinct; i++)
            {
              if (colours[i] == colour)
                {
                  counts[i]++;
                  break;
                }
            }

          if (i == distinct && distinct < (int)(sizeof(colours) /
                                                sizeof(colours[0])))
            {
              colours[distinct] = colour;
              counts[distinct] = 1;
              distinct++;
            }
        }
    }

  for (i = 0; i < distinct; i++)
    {
      if (counts[i] > best_count)
        {
          best_count = counts[i];
        }
    }

  stats->distinct     = distinct;
  stats->dominant_pct = samples > 0 ? (best_count * 100) / samples : 0;
  stats->max_grad     = max_grad;
  stats->sampled      = samples;

  return 0;
}

void dm_display_destroy(void)
{
  if (!g_created)
    {
      return;
    }

#if DM_DISPLAY_FBDEV
  if (g_fb_fd >= 0)
    {
      close(g_fb_fd);
      g_fb_fd = -1;
    }
#else
  if (g_mem_pixels != NULL)
    {
      free(g_mem_pixels);
      g_mem_pixels = NULL;
    }
#endif

  g_disp = NULL;
  g_created = false;
}

/****************************************************************************
 * apps/examples/deskmate/src/hal/dm_touch.h
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * Touch half of the DeskMate HAL.
 *
 * The board's touchscreen (/dev/input0) is attached by the display backend
 * through the LVGL NuttX glue.  On top of that this module always registers a
 * script-driven pointer indev, so the UI can be driven without any human and
 * without any input device: that is what makes the simulator and the goldfish
 * emulator runs scriptable, and it is also what dm_selftest uses to prove
 * that taps reach the widgets.
 ****************************************************************************/

#ifndef __APPS_EXAMPLES_DESKMATE_HAL_DM_TOUCH_H
#define __APPS_EXAMPLES_DESKMATE_HAL_DM_TOUCH_H

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <stdbool.h>

/****************************************************************************
 * Public Function Prototypes
 ****************************************************************************/

/* Register the script-driven pointer indev.  Returns 0 on success. */

int dm_touch_create(void);

/* Queue one pointer sample.  pressed=true is a touch-down, false a lift. */

void dm_touch_inject(int x, int y, bool pressed);

/* Queue a complete tap (down then up) at a point. */

void dm_touch_tap(int x, int y);

/* Number of queued samples not yet consumed by LVGL (for assertions). */

int dm_touch_pending(void);

/* Number of taps injected since start, and the last tap coordinates. */

unsigned int dm_touch_tap_count(void);
void dm_touch_last_tap(int *x, int *y);

#endif /* __APPS_EXAMPLES_DESKMATE_HAL_DM_TOUCH_H */

/****************************************************************************
 * apps/examples/deskmate/src/hal/dm_touch.c
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * Script-driven pointer indev: see dm_touch.h.
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <string.h>

#include <lvgl/lvgl.h>

#include "dm_log.h"
#include "hal/dm_touch.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define DM_TOUCH_QUEUE_LEN 16

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct dm_touch_sample_s
{
  int16_t x;
  int16_t y;
  bool    pressed;
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static lv_indev_t *g_indev;
static struct dm_touch_sample_s g_queue[DM_TOUCH_QUEUE_LEN];
static volatile int g_head;      /* Next write slot */
static volatile int g_tail;      /* Next read slot */
static unsigned int g_taps;
static int g_last_x;
static int g_last_y;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static int dm_touch_count(void)
{
  int count = g_head - g_tail;

  if (count < 0)
    {
      count += DM_TOUCH_QUEUE_LEN;
    }

  return count;
}

static void dm_touch_read_cb(lv_indev_t *indev, lv_indev_data_t *data)
{
  (void)indev;

  if (dm_touch_count() > 0)
    {
      struct dm_touch_sample_s *s = &g_queue[g_tail];

      data->point.x = s->x;
      data->point.y = s->y;
      data->state   = s->pressed ? LV_INDEV_STATE_PRESSED
                                 : LV_INDEV_STATE_RELEASED;

      g_tail = (g_tail + 1) % DM_TOUCH_QUEUE_LEN;
    }
  else
    {
      /* Hold the pointer where it was and report it released, which is what
       * a real panel reports while nobody touches it.
       */

      data->point.x = g_last_x;
      data->point.y = g_last_y;
      data->state   = LV_INDEV_STATE_RELEASED;
    }

  data->continue_reading = false;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

void dm_touch_inject(int x, int y, bool pressed)
{
  int next = (g_head + 1) % DM_TOUCH_QUEUE_LEN;

  if (next == g_tail)
    {
      DM_WARN("touch queue full, dropping sample (%d,%d)", x, y);
      return;
    }

  g_queue[g_head].x       = (int16_t)x;
  g_queue[g_head].y       = (int16_t)y;
  g_queue[g_head].pressed = pressed;
  g_head = next;

  g_last_x = x;
  g_last_y = y;

  DM_LOG("touch %s at (%d,%d)", pressed ? "down" : "up", x, y);
}

void dm_touch_tap(int x, int y)
{
  dm_touch_inject(x, y, true);
  dm_touch_inject(x, y, false);

  g_taps++;
  g_last_x = x;
  g_last_y = y;

  DM_LOG("tap #%u at (%d,%d)", g_taps, x, y);
}

int dm_touch_pending(void)
{
  return dm_touch_count();
}

unsigned int dm_touch_tap_count(void)
{
  return g_taps;
}

void dm_touch_last_tap(int *x, int *y)
{
  if (x != NULL)
    {
      *x = g_last_x;
    }

  if (y != NULL)
    {
      *y = g_last_y;
    }
}

int dm_touch_create(void)
{
  g_head = 0;
  g_tail = 0;

  g_indev = lv_indev_create();
  if (g_indev == NULL)
    {
      DM_ERR("lv_indev_create failed");
      return -1;
    }

  lv_indev_set_type(g_indev, LV_INDEV_TYPE_POINTER);
  lv_indev_set_read_cb(g_indev, dm_touch_read_cb);

  DM_LOG("touch: script indev ready");
  return 0;
}

