/****************************************************************************
 * apps/examples/deskmate/src/ui/dm_ui.c
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * The DeskMate widget tree.  Milestone 1 builds the home page: a status bar, a
 * system card, an interactive tap card that proves touch input reaches the
 * widgets, and a footer.  Later milestones add the camera, chat, network and
 * settings pages on top of the same helpers.
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdio.h>
#include <string.h>
#include <time.h>

#include <lvgl/lvgl.h>

#include "dm_config.h"
#include "dm_log.h"
#include "hal/dm_display.h"
#include "ui/dm_i18n.h"
#include "ui/dm_ui.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#if defined(LV_FONT_MONTSERRAT_28) && LV_FONT_MONTSERRAT_28
#  define DM_FONT_TITLE (&lv_font_montserrat_28)
#else
#  define DM_FONT_TITLE LV_FONT_DEFAULT
#endif

#if defined(LV_FONT_MONTSERRAT_20) && LV_FONT_MONTSERRAT_20
#  define DM_FONT_BODY (&lv_font_montserrat_20)
#else
#  define DM_FONT_BODY LV_FONT_DEFAULT
#endif

#define DM_COL_BG       0x0f1319
#define DM_COL_CARD     0x1b2230
#define DM_COL_CARD2    0x222c3d
#define DM_COL_ACCENT   0x4c9aff
#define DM_COL_TEXT     0xe8eef6
#define DM_COL_MUTED    0x8d9bb0

/****************************************************************************
 * Private Data
 ****************************************************************************/

static lv_obj_t *g_time_label;
static lv_obj_t *g_uptime_label;
static lv_obj_t *g_geo_label;
static lv_obj_t *g_counter_label;
static lv_obj_t *g_tap_button;
static int       g_tap_count;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static void dm_style_card(lv_obj_t *obj, lv_color_t bg)
{
  lv_obj_set_style_bg_color(obj, bg, 0);
  lv_obj_set_style_bg_opa(obj, LV_OPA_COVER, 0);
  lv_obj_set_style_border_width(obj, 0, 0);
  lv_obj_set_style_radius(obj, 12, 0);
  lv_obj_set_style_pad_all(obj, 14, 0);
}

static lv_obj_t *dm_label(lv_obj_t *parent, const char *text,
                          const lv_font_t *font, lv_color_t colour)
{
  lv_obj_t *label = lv_label_create(parent);

  lv_label_set_text(label, text);
  lv_obj_set_style_text_font(label, font, 0);
  lv_obj_set_style_text_color(label, colour, 0);

  return label;
}

static void dm_tap_event_cb(lv_event_t *event)
{
  lv_event_code_t code = lv_event_get_code(event);

  if (code != LV_EVENT_CLICKED)
    {
      return;
    }

  g_tap_count++;

  if (g_counter_label != NULL)
    {
      lv_label_set_text_fmt(g_counter_label, "%d %s", g_tap_count,
                            DM_I18N_TAP_COUNT);
    }

  DM_LOG("ui: tap %d handled by the button", g_tap_count);
}

static void dm_refresh_clock(void)
{
  time_t now = time(NULL);
  struct tm tm_buf;
  char text[32];

  if (localtime_r(&now, &tm_buf) == NULL)
    {
      return;
    }

  strftime(text, sizeof(text), "%H:%M:%S", &tm_buf);

  if (g_time_label != NULL)
    {
      lv_label_set_text(g_time_label, text);
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int dm_ui_create(void)
{
  const struct dm_display_metrics_s *metrics = dm_display_metrics();
  lv_obj_t *screen;
  lv_obj_t *bar;
  lv_obj_t *card;
  lv_obj_t *title;
  lv_obj_t *value;
  int width;
  int height;
  int margin = 16;
  int bar_h;
  int card_h;
  int y;

  if (metrics == NULL)
    {
      DM_ERR("ui: display not ready");
      return -1;
    }

  width  = metrics->width;
  height = metrics->height;

  screen = lv_screen_active();
  lv_obj_remove_style_all(screen);
  lv_obj_set_style_bg_color(screen, lv_color_hex(DM_COL_BG), 0);
  lv_obj_set_style_bg_opa(screen, LV_OPA_COVER, 0);

  /* Status bar ------------------------------------------------------------ */

  bar_h = DM_STATUS_BAR_H;

  bar = lv_obj_create(screen);
  lv_obj_remove_style_all(bar);
  lv_obj_set_pos(bar, 0, 0);
  lv_obj_set_size(bar, width, bar_h);
  lv_obj_set_style_bg_color(bar, lv_color_hex(DM_COL_CARD), 0);
  lv_obj_set_style_bg_opa(bar, LV_OPA_COVER, 0);
  lv_obj_set_style_pad_left(bar, margin, 0);
  lv_obj_set_style_pad_right(bar, margin, 0);

  title = dm_label(bar, DM_I18N_APP_TITLE, DM_FONT_TITLE,
                   lv_color_hex(DM_COL_TEXT));
  lv_obj_align(title, LV_ALIGN_LEFT_MID, 0, 0);

  g_time_label = dm_label(bar, "--:--:--", DM_FONT_BODY,
                          lv_color_hex(DM_COL_ACCENT));
  lv_obj_align(g_time_label, LV_ALIGN_RIGHT_MID, 0, 0);

  /* System card ----------------------------------------------------------- */

  y = bar_h + margin;
  card_h = (height - y - DM_FOOTER_H - 2 * margin) * 3 / 5;
  if (card_h < 120)
    {
      card_h = height - y - DM_FOOTER_H - 2 * margin;
      if (card_h < 80)
        {
          card_h = height - y - margin;
        }
    }

  card = lv_obj_create(screen);
  lv_obj_remove_style_all(card);
  lv_obj_set_pos(card, margin, y);
  lv_obj_set_size(card, width - 2 * margin, card_h);
  dm_style_card(card, lv_color_hex(DM_COL_CARD));
  lv_obj_set_flex_flow(card, LV_FLEX_FLOW_COLUMN);
  lv_obj_set_flex_align(card, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_START,
                        LV_FLEX_ALIGN_START);
  lv_obj_set_style_pad_row(card, 6, 0);

  dm_label(card, DM_I18N_SYSTEM_CARD, DM_FONT_BODY, lv_color_hex(DM_COL_ACCENT));

  g_geo_label = dm_label(card, "", DM_FONT_BODY, lv_color_hex(DM_COL_TEXT));
  lv_label_set_text_fmt(g_geo_label, "%s %dx%d RGB565 (%s)",
                        DM_I18N_DISPLAY, metrics->width, metrics->height,
                        metrics->backend);

  value = dm_label(card, "", DM_FONT_BODY, lv_color_hex(DM_COL_MUTED));
  lv_label_set_text_fmt(value, "%s %s", DM_I18N_LVGL, lv_version_info());

  value = dm_label(card, "", DM_FONT_BODY, lv_color_hex(DM_COL_MUTED));
  lv_label_set_text_fmt(value, "%s %s %s", DM_I18N_BUILD, DM_APP_NAME,
                        DM_APP_VERSION);

  g_uptime_label = dm_label(card, "", DM_FONT_BODY, lv_color_hex(DM_COL_MUTED));
  lv_label_set_text(g_uptime_label, DM_I18N_UPTIME ": 0 s");

  /* Touch card ------------------------------------------------------------ */

  y += card_h + margin;
  card_h = height - DM_FOOTER_H - margin - y;
  if (card_h < 96)
    {
      card_h = 96;
    }

  card = lv_obj_create(screen);
  lv_obj_remove_style_all(card);
  lv_obj_set_pos(card, margin, y);
  lv_obj_set_size(card, width - 2 * margin, card_h);
  dm_style_card(card, lv_color_hex(DM_COL_CARD2));

  dm_label(card, DM_I18N_TOUCH_CARD, DM_FONT_BODY,
           lv_color_hex(DM_COL_ACCENT));

  g_tap_button = lv_button_create(card);
  lv_obj_set_size(g_tap_button, 140, 52);
  lv_obj_align(g_tap_button, LV_ALIGN_LEFT_MID, 0, 12);
  lv_obj_set_style_bg_color(g_tap_button, lv_color_hex(DM_COL_ACCENT), 0);
  lv_obj_set_style_radius(g_tap_button, 10, 0);
  lv_obj_add_event_cb(g_tap_button, dm_tap_event_cb, LV_EVENT_CLICKED, NULL);

  {
    lv_obj_t *btn_label = dm_label(g_tap_button, DM_I18N_TAP_BUTTON,
                                   DM_FONT_BODY, lv_color_hex(0x08131f));
    lv_obj_center(btn_label);
  }

  g_counter_label = dm_label(card, "", DM_FONT_BODY, lv_color_hex(DM_COL_TEXT));
  lv_label_set_text_fmt(g_counter_label, "0 %s", DM_I18N_TAP_COUNT);
  lv_obj_align_to(g_counter_label, g_tap_button, LV_ALIGN_OUT_RIGHT_MID, 18, 0);

  {
    lv_obj_t *hint = dm_label(card, DM_I18N_TAP_HINT, LV_FONT_DEFAULT,
                              lv_color_hex(DM_COL_MUTED));
    lv_obj_align(hint, LV_ALIGN_BOTTOM_LEFT, 0, 0);
  }

  /* Footer ---------------------------------------------------------------- */

  {
    lv_obj_t *footer = dm_label(screen, DM_I18N_HOME "  -  "
                                DM_I18N_APP_SUBTITLE, LV_FONT_DEFAULT,
                                lv_color_hex(DM_COL_MUTED));
    lv_obj_align(footer, LV_ALIGN_BOTTOM_LEFT, margin, -10);
  }

  dm_refresh_clock();

  DM_LOG("ui: home page built (%d top-level objects)",
         (int)lv_obj_get_child_count(screen));
  return 0;
}

void dm_ui_tick(void)
{
  static unsigned int last_second;
  struct timespec ts;
  unsigned int now_s;

  dm_refresh_clock();

  if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
    {
      return;
    }

  now_s = (unsigned int)ts.tv_sec;
  if (now_s == last_second)
    {
      return;
    }

  last_second = now_s;

  if (g_uptime_label != NULL)
    {
      lv_label_set_text_fmt(g_uptime_label, DM_I18N_UPTIME ": %u s", now_s);
    }
}

int dm_ui_tap_count(void)
{
  return g_tap_count;
}

int dm_ui_tap_target(int *x, int *y)
{
  lv_area_t area;

  if (g_tap_button == NULL)
    {
      return -1;
    }

  lv_obj_get_coords(g_tap_button, &area);

  if (x != NULL)
    {
      *x = (area.x1 + area.x2) / 2;
    }

  if (y != NULL)
    {
      *y = (area.y1 + area.y2) / 2;
    }

  return 0;
}

int dm_ui_object_count(void)
{
  lv_obj_t *screen = lv_screen_active();

  if (screen == NULL)
    {
      return 0;
    }

  return (int)lv_obj_get_child_count(screen);
}

/****************************************************************************
 * apps/examples/deskmate/src/dm_selftest.c
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * See dm_selftest.h for the scenario.
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <stdio.h>
#include <string.h>

#include <lvgl/lvgl.h>

#include "dm_config.h"
#include "dm_log.h"
#include "dm_selftest.h"
#include "hal/dm_display.h"
#include "hal/dm_touch.h"
#include "ui/dm_ui.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Loop iterations granted to LVGL between injecting a tap and checking its
 * effect: the indev is sampled inside lv_timer_handler().
 */

#define DM_SELFTEST_TAP_FRAMES 8

#define DM_SELFTEST_MAX_CHECKS 8

/****************************************************************************
 * Private Types
 ****************************************************************************/

enum dm_selftest_state_e
{
  DM_ST_IDLE = 0,
  DM_ST_TAP_WAIT,
  DM_ST_DONE
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static enum dm_selftest_state_e g_state = DM_ST_IDLE;
static char g_snap_path[128];
static int  g_frames;
static int  g_checks;
static int  g_failures;
static int  g_result = -1;
static int  g_taps_before;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static void dm_check(const char *name, bool ok, const char *detail)
{
  g_checks++;

  if (!ok)
    {
      g_failures++;
    }

  printf("[dm-check] %-28s %s %s\n", name, ok ? "PASS" : "FAIL",
         detail != NULL ? detail : "");
  fflush(stdout);
}

void dm_selftest_begin(const char *snap_path)
{
  g_checks    = 0;
  g_failures  = 0;
  g_frames    = 0;
  g_result    = -1;
  g_state     = DM_ST_TAP_WAIT;

  if (snap_path != NULL && snap_path[0] != '\0')
    {
      strlcpy(g_snap_path, snap_path, sizeof(g_snap_path));
    }
  else
    {
      strlcpy(g_snap_path, DM_SNAP_HOST_DIR "/dm_home.bin",
              sizeof(g_snap_path));
    }

  /* Checks that can be answered straight away. */

  {
    const struct dm_display_metrics_s *metrics = dm_display_metrics();
    char detail[96];

    if (metrics == NULL)
      {
        dm_check("display:ready", false, "no metrics");
      }
    else
      {
        snprintf(detail, sizeof(detail), "%dx%d %dbpp %s", metrics->width,
                 metrics->height, metrics->bpp, metrics->backend);
        dm_check("display:ready",
                 metrics->width > 0 && metrics->height > 0 &&
                 metrics->pixels != NULL && metrics->pixels_size > 0,
                 detail);
      }
  }

  {
    char detail[48];

    snprintf(detail, sizeof(detail), "%s", lv_version_info());
    dm_check("lvgl:version", lv_version_major() == 9, detail);
  }

  {
    char detail[48];
    int objects = dm_ui_object_count();

    snprintf(detail, sizeof(detail), "%d objects", objects);
    dm_check("ui:built", objects >= 3, detail);
  }

  /* Touch: aim at the button and let LVGL consume the sample. */

  {
    int x = 0;
    int y = 0;

    g_taps_before = dm_ui_tap_count();

    if (dm_ui_tap_target(&x, &y) != 0)
      {
        dm_check("touch:target", false, "no tap target");
        g_frames = 0;
      }
    else
      {
        char detail[48];

        snprintf(detail, sizeof(detail), "(%d,%d)", x, y);
        dm_check("touch:target", x > 0 && y > 0, detail);
        dm_touch_tap(x, y);
        g_frames = DM_SELFTEST_TAP_FRAMES;
      }
  }

  DM_LOG("selftest: scenario started, snapshot target %s", g_snap_path);
}

void dm_selftest_step(void)
{
  if (g_state != DM_ST_TAP_WAIT)
    {
      return;
    }

  if (g_frames > 0)
    {
      g_frames--;
      return;
    }

  /* Did the tap reach the widget? */

  {
    int now = dm_ui_tap_count();
    char detail[48];

    snprintf(detail, sizeof(detail), "%d -> %d", g_taps_before, now);
    dm_check("touch:delivered", now > g_taps_before, detail);
  }

  /* Snapshot and picture statistics. */

  {
    const struct dm_display_metrics_s *metrics = dm_display_metrics();
    int written;

    written = dm_display_snapshot(g_snap_path);

    if (metrics == NULL)
      {
        dm_check("snapshot:written", false, "no metrics");
      }
    else
      {
        char detail[96];

        snprintf(detail, sizeof(detail), "%d bytes (expected %u)", written,
                 (unsigned)metrics->pixels_size);
        dm_check("snapshot:written",
                 written > 0 && (size_t)written == metrics->pixels_size,
                 detail);
      }

    {
      struct dm_display_stats_s stats;

      memset(&stats, 0, sizeof(stats));

      if (dm_display_stats(&stats) != 0)
        {
          dm_check("snapshot:picture", false, "stats failed");
        }
      else
        {
          char detail[96];

          snprintf(detail, sizeof(detail),
                   "distinct=%d dominant=%d%% grad=%d n=%d",
                   stats.distinct, stats.dominant_pct, stats.max_grad,
                   stats.sampled);

          /* A drawn UI has several colours and no wild gradients; a blank
           * frame has one, a noise field has both extremes.
           */

          dm_check("snapshot:picture",
                   stats.distinct >= 3 && stats.dominant_pct <= 99 &&
                   stats.max_grad <= 4096, detail);
        }
    }
  }

  g_state = DM_ST_DONE;

  if (g_failures == 0)
    {
      g_result = 0;
      printf("DM-SELFTEST RESULT: PASS (%d/%d)\n", g_checks, g_checks);
    }
  else
    {
      g_result = -1;
      printf("DM-SELFTEST RESULT: FAIL (%d/%d failed)\n", g_failures,
             g_checks);
    }

  fflush(stdout);
}

bool dm_selftest_active(void)
{
  return g_state != DM_ST_DONE && g_state != DM_ST_IDLE;
}

int dm_selftest_result(void)
{
  return g_result;
}

/****************************************************************************
 * apps/examples/deskmate/deskmate_main.c
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * DeskMate -- the openvela control-panel application layer.
 *
 * NSH built-in:
 *
 *   nsh> deskmate                     run the UI
 *   nsh> deskmate --selftest          headless scenario + snapshot + report
 *   nsh> deskmate --exit-after 30     stop after 30 seconds
 *   nsh> deskmate --snap /tmp/x.bin   snapshot destination
 *
 * The run is single threaded on purpose: LVGL and the widget tree are only
 * ever touched from the loop below, so there is no cross-thread invalidation
 * to get wrong.
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <time.h>
#include <unistd.h>

#if defined(CONFIG_BOARDCTL) && !defined(CONFIG_NSH_ARCHINIT)
#  include <sys/boardctl.h>
#endif

#if defined(CONFIG_FS_HOSTFS)
#  include <sys/mount.h>
#endif

#include <lvgl/lvgl.h>

#include "dm_config.h"
#include "dm_log.h"
#include "dm_selftest.h"
#include "hal/dm_display.h"
#include "hal/dm_touch.h"
#include "ui/dm_ui.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Longest sleep between loop iterations: keeps exit conditions and the
 * self-test responsive even when LVGL has nothing to do.
 */

#define DM_MAX_SLEEP_MS 40

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const char *g_usage =
  "Usage: " DM_PROGNAME " [options]\n"
  "  --selftest          run the headless scenario, print the report and exit\n"
  "  --snap <path>       snapshot destination (default " DM_SNAP_HOST_DIR "/dm_home.bin)\n"
  "  --exit-after <sec>  leave the UI loop after <sec> seconds\n"
  "  --help              this text\n";

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static unsigned int dm_now_ms(void)
{
  struct timespec ts;

  if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
    {
      return 0;
    }

  return (unsigned int)(ts.tv_sec * 1000u + ts.tv_nsec / 1000000u);
}

/* Mount the host directory the simulator uses to hand snapshots out, when one
 * is configured.  Failure is reported but never fatal: a run without hostfs
 * still produces console evidence.
 */

static void dm_mount_hostfs(void)
{
#if defined(CONFIG_FS_HOSTFS)
  if (DM_HOSTFS_PATH[0] == '\0')
    {
      return;
    }

  (void)mkdir("/host", 0777);

  if (mount(NULL, "/host", "hostfs", 0, "fs=" DM_HOSTFS_PATH) < 0)
    {
      DM_WARN("hostfs mount of %s failed: %d", DM_HOSTFS_PATH, errno);
      return;
    }

  (void)mkdir(DM_SNAP_HOST_DIR, 0777);
  DM_LOG("hostfs: %s mounted at /host", DM_HOSTFS_PATH);
#else
  DM_LOG("hostfs: not enabled in this configuration");
#endif
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  const char *snap_path = NULL;
  bool selftest = false;
  unsigned int exit_after_ms = (unsigned int)DM_EXIT_AFTER * 1000u;
  unsigned int start_ms;
  int result = 0;
  int i;

  for (i = 1; i < argc; i++)
    {
      if (strcmp(argv[i], "--selftest") == 0)
        {
          selftest = true;
        }
      else if (strcmp(argv[i], "--snap") == 0 && i + 1 < argc)
        {
          snap_path = argv[++i];
        }
      else if (strcmp(argv[i], "--exit-after") == 0 && i + 1 < argc)
        {
          exit_after_ms = (unsigned int)atoi(argv[++i]) * 1000u;
        }
      else if (strcmp(argv[i], "--help") == 0 || strcmp(argv[i], "-h") == 0)
        {
          printf("%s", g_usage);
          return 0;
        }
      else
        {
          DM_WARN("ignoring unknown argument '%s'", argv[i]);
        }
    }

  DM_LOG("%s %s starting (selftest=%d)", DM_APP_NAME, DM_APP_VERSION,
         (int)selftest);

  dm_mount_hostfs();

#if defined(CONFIG_BOARDCTL) && !defined(CONFIG_NSH_ARCHINIT)
  boardctl(BOARDIOC_INIT, 0);
#endif

  if (lv_is_initialized())
    {
      DM_ERR("LVGL is already initialised; refusing to run twice");
      return 1;
    }

  lv_init();

  if (dm_display_create() != 0)
    {
      DM_ERR("display bring-up failed");
      lv_deinit();
      return 1;
    }

  if (dm_touch_create() != 0)
    {
      DM_ERR("touch bring-up failed");
      dm_display_destroy();
      lv_deinit();
      return 1;
    }

  if (dm_ui_create() != 0)
    {
      DM_ERR("UI build failed");
      dm_display_destroy();
      lv_deinit();
      return 1;
    }

  {
    const struct dm_display_metrics_s *metrics = dm_display_metrics();

    printf("DM-READY display=%s %dx%d bpp=%d lvgl=%s\n",
           metrics != NULL ? metrics->backend : "none",
           metrics != NULL ? metrics->width : 0,
           metrics != NULL ? metrics->height : 0,
           metrics != NULL ? metrics->bpp : 0, lv_version_info());
    fflush(stdout);
  }

  if (selftest)
    {
      dm_selftest_begin(snap_path);

      /* Give LVGL a couple of frames to draw the freshly built tree before
       * the scenario starts poking at it.
       */

      for (i = 0; i < 4; i++)
        {
          lv_timer_handler();
          usleep(5000);
        }
    }

  start_ms = dm_now_ms();

  for (; ; )
    {
      uint32_t idle = lv_timer_handler();
      unsigned int elapsed = dm_now_ms() - start_ms;

      dm_ui_tick();

      if (dm_selftest_active())
        {
          dm_selftest_step();
        }

      if (selftest && !dm_selftest_active())
        {
          result = dm_selftest_result() == 0 ? 0 : 1;
          break;
        }

      if (exit_after_ms > 0 && elapsed >= exit_after_ms)
        {
          DM_LOG("exit-after reached (%u ms)", exit_after_ms);
          break;
        }

      if (idle == 0)
        {
          idle = 1;
        }
      else if (idle > DM_MAX_SLEEP_MS)
        {
          idle = DM_MAX_SLEEP_MS;
        }

      usleep(idle * 1000);
    }

  dm_display_destroy();
  lv_deinit();

  printf("DM-EXIT %s result=%d\n", selftest ? "selftest" : "run", result);
  fflush(stdout);

  return result;
}

