/****************************************************************************
 * apps/examples/deskmate/src/hal/dm_net.h
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * Network half of the DeskMate HAL.
 *
 * Two things are exposed, because the product UI needs both:
 *
 *   ethernet / generic interfaces : name, up/running, IPv4 address.  Read from
 *       getifaddrs() + SIOCGIFFLAGS, so it covers the ESP32-P4 EMAC (eth0),
 *       the simulator TAP device and any other NuttX netdev.
 *
 *   WiFi                          : the WAPI ioctl surface (SIOCGIWESSID,
 *       SIOCGIWSCAN, SIOCSIWESSID, SIOCSIWENCODEEXT).  This is what the
 *       on-board ESP-Hosted path exposes and what the simulator's wifi_sim
 *       pseudo device exposes, so the same UI code drives both.
 *
 * Everything is best effort: a board without WiFi reports "no wireless
 * interface" instead of failing, and the UI degrades to the wired status.
 ****************************************************************************/

#ifndef __APPS_EXAMPLES_DESKMATE_HAL_DM_NET_H
#define __APPS_EXAMPLES_DESKMATE_HAL_DM_NET_H

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <stdbool.h>
#include <stddef.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define DM_NET_MAX_IFS   4
#define DM_NET_MAX_IFSZ  8
#define DM_NET_MAX_APS   8
#define DM_NET_SSID_LEN  33

/****************************************************************************
 * Public Types
 ****************************************************************************/

struct dm_net_if_s
{
  char name[DM_NET_MAX_IFSZ];
  bool up;
  bool running;
  bool wireless;
  char ip[20];
  char mask[20];
};

struct dm_wifi_ap_s
{
  char ssid[DM_NET_SSID_LEN];
  char bssid[18];
  int  rssi;                    /* dBm (negative), 0 when unknown */
  int  freq;                    /* MHz, 0 when unknown */
  bool secure;
};

struct dm_net_status_s
{
  int  count;
  struct dm_net_if_s ifs[DM_NET_MAX_IFS];
  char primary[DM_NET_MAX_IFSZ];  /* Interface that carries the address */
  bool online;                    /* Some interface is up with an address */
  bool wireless_present;
};

/****************************************************************************
 * Public Function Prototypes
 ****************************************************************************/

/* Re-read the interface list.  Returns 0 on success. */

int dm_net_refresh(void);

/* Last snapshot; NULL before the first dm_net_refresh(). */

const struct dm_net_status_s *dm_net_status(void);

/* Connect state of the wireless interface: SSID and signal, empty when not
 * associated.  Returns 0 when a wireless interface exists, -ENODEV otherwise.
 */

int dm_net_wifi_link(char *ssid, size_t ssid_len, int *rssi);

/* Trigger a scan and return the access points found.  Returns the number of
 * APs (>= 0) or a negated errno when scanning is unavailable.
 */

int dm_net_wifi_scan(struct dm_wifi_ap_s *aps, int max_aps);

/* Associate with an AP.  psk may be NULL/empty for an open network.
 * Returns 0 on success.
 */

int dm_net_wifi_connect(const char *ssid, const char *psk);

/* Disassociate. */

int dm_net_wifi_disconnect(void);

/* One-line summary of the interface list, for the console evidence. */

int dm_net_describe(char *buf, size_t len);

#endif /* __APPS_EXAMPLES_DESKMATE_HAL_DM_NET_H */

/****************************************************************************
 * apps/examples/deskmate/src/hal/dm_net.c
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * Network half of the DeskMate HAL: see dm_net.h.
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <net/if.h>
#include <netinet/in.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <unistd.h>

#if defined(CONFIG_NET) && defined(CONFIG_LIBC_NETDB)
#  include <ifaddrs.h>
#endif

#include <arpa/inet.h>

#if defined(CONFIG_NET) && defined(CONFIG_NETDEV_WIRELESS_IOCTL)
#  include <nuttx/wireless/wireless.h>
#  define DM_HAVE_WAPI 1
#endif

#include "dm_log.h"
#include "hal/dm_net.h"

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct dm_net_status_s g_status;
static int g_sock = -1;
static bool g_refreshed;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static int dm_net_socket(void)
{
  if (g_sock < 0)
    {
      g_sock = socket(AF_INET, SOCK_DGRAM, 0);
      if (g_sock < 0)
        {
          DM_ERR("net: socket() failed: %d", errno);
        }
    }

  return g_sock;
}

static struct dm_net_if_s *dm_net_find_if(const char *name)
{
  int i;

  for (i = 0; i < g_status.count; i++)
    {
      if (strcmp(g_status.ifs[i].name, name) == 0)
        {
          return &g_status.ifs[i];
        }
    }

  if (g_status.count >= DM_NET_MAX_IFS)
    {
      return NULL;
    }

  struct dm_net_if_s *entry = &g_status.ifs[g_status.count++];

  memset(entry, 0, sizeof(*entry));
  strlcpy(entry->name, name, sizeof(entry->name));

  return entry;
}

static void dm_net_fill_flags(struct dm_net_if_s *entry)
{
#if defined(CONFIG_NET)
  struct ifreq ifr;

  if (dm_net_socket() < 0)
    {
      return;
    }

  memset(&ifr, 0, sizeof(ifr));
  strlcpy(ifr.ifr_name, entry->name, IFNAMSIZ);

  if (ioctl(g_sock, SIOCGIFFLAGS, (unsigned long)&ifr) == 0)
    {
      entry->up      = (ifr.ifr_flags & IFF_UP) != 0;
      entry->running = (ifr.ifr_flags & IFF_RUNNING) != 0;
    }

  /* A wireless interface answers SIOCGIWNAME; that is the portable probe. */

#ifdef DM_HAVE_WAPI
  {
    struct iwreq iwr;

    memset(&iwr, 0, sizeof(iwr));
    strlcpy(iwr.ifr_name, entry->name, IFNAMSIZ);

    if (ioctl(g_sock, SIOCGIWNAME, (unsigned long)&iwr) == 0)
      {
        entry->wireless = true;
      }
  }
#endif
#endif
}

#ifdef DM_HAVE_WAPI
/* Pick a wireless interface to talk to. */

static const char *dm_net_wifi_ifname(void)
{
  int i;

  for (i = 0; i < g_status.count; i++)
    {
      if (g_status.ifs[i].wireless)
        {
          return g_status.ifs[i].name;
        }
    }

  return NULL;
}

/* The SSID of a scan event is stored either right after the iw_point header
 * (the layout the NuttX WAPI drivers use) or at an offset from the start of
 * the result buffer (the original WE-18 layout).  Accept both.
 */

static const char *dm_wifi_event_ssid(const struct iw_event *ev,
                                      const char *base,
                                      size_t total)
{
  uintptr_t ptr = (uintptr_t)ev->u.essid.pointer;
  size_t len = ev->u.essid.length;

  if (len == 0 || len > DM_NET_SSID_LEN)
    {
      return NULL;
    }

  if (ptr >= (uintptr_t)sizeof(struct iw_point))
    {
      return (const char *)&ev->u.essid + sizeof(struct iw_point);
    }

  if (ptr + len <= total)
    {
      return base + ptr;
    }

  return NULL;
}
#endif

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int dm_net_refresh(void)
{
  memset(&g_status, 0, sizeof(g_status));

#if defined(CONFIG_NET) && defined(CONFIG_LIBC_NETDB)
  {
    struct ifaddrs *list = NULL;
    struct ifaddrs *ifa;

    if (getifaddrs(&list) != 0)
      {
        DM_WARN("net: getifaddrs failed: %d", errno);
        return -errno;
      }

    for (ifa = list; ifa != NULL; ifa = ifa->ifa_next)
      {
        struct dm_net_if_s *entry;
        struct sockaddr_in *sin;

        if (ifa->ifa_name == NULL || ifa->ifa_addr == NULL)
          {
            continue;
          }

        if (ifa->ifa_addr->sa_family != AF_INET)
          {
            continue;
          }

        if (strcmp(ifa->ifa_name, "lo") == 0)
          {
            continue;
          }

        entry = dm_net_find_if(ifa->ifa_name);
        if (entry == NULL)
          {
            continue;
          }

        dm_net_fill_flags(entry);

        sin = (struct sockaddr_in *)ifa->ifa_addr;
        (void)inet_ntop(AF_INET, &sin->sin_addr, entry->ip,
                        sizeof(entry->ip));

        if (ifa->ifa_netmask != NULL)
          {
            sin = (struct sockaddr_in *)ifa->ifa_netmask;
            (void)inet_ntop(AF_INET, &sin->sin_addr, entry->mask,
                            sizeof(entry->mask));
          }
      }

    freeifaddrs(list);
  }
#endif

  /* Interfaces that exist but have no IPv4 address yet still matter (the UI
   * shows "link up, no address"), so fill their flags in too.
   */

#ifdef DM_HAVE_WAPI
  {
    struct dm_net_if_s *entry = dm_net_find_if("wlan0");

    if (entry != NULL)
      {
        dm_net_fill_flags(entry);
      }
  }
#endif

  for (int i = 0; i < g_status.count; i++)
    {
      if (g_status.ifs[i].wireless)
        {
          g_status.wireless_present = true;
        }

      if (g_status.ifs[i].up && g_status.ifs[i].ip[0] != '\0' &&
          strcmp(g_status.ifs[i].ip, "0.0.0.0") != 0)
        {
          g_status.online = true;

          if (g_status.primary[0] == '\0')
            {
              strlcpy(g_status.primary, g_status.ifs[i].name,
                      sizeof(g_status.primary));
            }
        }
    }

  /* Prefer the wireless interface as the primary one when it is associated:
   * that is what the product narrative promises.
   */

  if (g_status.wireless_present)
    {
      for (int i = 0; i < g_status.count; i++)
        {
          if (g_status.ifs[i].wireless && g_status.ifs[i].up &&
              g_status.ifs[i].ip[0] != '\0' &&
              strcmp(g_status.ifs[i].ip, "0.0.0.0") != 0)
            {
              strlcpy(g_status.primary, g_status.ifs[i].name,
                      sizeof(g_status.primary));
              break;
            }
        }
    }

  g_refreshed = true;
  return 0;
}

const struct dm_net_status_s *dm_net_status(void)
{
  return g_refreshed ? &g_status : NULL;
}

int dm_net_wifi_link(char *ssid, size_t ssid_len, int *rssi)
{
  if (ssid != NULL && ssid_len > 0)
    {
      ssid[0] = '\0';
    }

  if (rssi != NULL)
    {
      *rssi = 0;
    }

#ifdef DM_HAVE_WAPI
  {
    const char *ifname = dm_net_wifi_ifname();
    struct iwreq iwr;
    char buf[DM_NET_SSID_LEN];

    if (ifname == NULL || dm_net_socket() < 0)
      {
        return -ENODEV;
      }

    memset(buf, 0, sizeof(buf));
    memset(&iwr, 0, sizeof(iwr));
    strlcpy(iwr.ifr_name, ifname, IFNAMSIZ);
    iwr.u.essid.pointer = buf;
    iwr.u.essid.length  = sizeof(buf);
    iwr.u.essid.flags   = 1;

    if (ioctl(g_sock, SIOCGIWESSID, (unsigned long)&iwr) < 0)
      {
        return -errno;
      }

    if (ssid != NULL && ssid_len > 0 && iwr.u.essid.length > 0)
      {
        size_t len = iwr.u.essid.length;

        if (len >= ssid_len)
          {
            len = ssid_len - 1;
          }

        memcpy(ssid, buf, len);
        ssid[len] = '\0';
      }

    return 0;
  }
#else
  return -ENODEV;
#endif
}

int dm_net_wifi_scan(struct dm_wifi_ap_s *aps, int max_aps)
{
#ifdef DM_HAVE_WAPI
  const char *ifname = dm_net_wifi_ifname();
  static char scan_buf[2048];
  struct iwreq iwr;
  struct iw_event *ev;
  struct dm_wifi_ap_s *cur = NULL;
  int found = 0;
  size_t off = 0;
  size_t total;

  if (ifname == NULL || dm_net_socket() < 0)
    {
      return -ENODEV;
    }

  if (aps == NULL || max_aps <= 0)
    {
      return -EINVAL;
    }

  memset(aps, 0, sizeof(*aps) * max_aps);

  /* Ask for a scan, then read what the driver collected.  The first call only
   * kicks the state machine off; a driver that is already scanning answers
   * with the results on the second call.
   */

  memset(&iwr, 0, sizeof(iwr));
  strlcpy(iwr.ifr_name, ifname, IFNAMSIZ);

  if (ioctl(g_sock, SIOCSIWSCAN, (unsigned long)&iwr) < 0 &&
      errno != EINPROGRESS && errno != EAGAIN)
    {
      DM_LOG("wifi: scan not supported (%d)", errno);
      return -errno;
    }

  memset(&iwr, 0, sizeof(iwr));
  strlcpy(iwr.ifr_name, ifname, IFNAMSIZ);
  iwr.u.data.pointer = scan_buf;
  iwr.u.data.length  = sizeof(scan_buf);
  iwr.u.data.flags   = 0;

  if (ioctl(g_sock, SIOCGIWSCAN, (unsigned long)&iwr) < 0)
    {
      if (errno == E2BIG)
        {
          DM_WARN("wifi: scan list larger than %u bytes",
                  (unsigned)sizeof(scan_buf));
        }
      else
        {
          DM_LOG("wifi: scan results unavailable (%d)", errno);
        }

      return -errno;
    }

  total = iwr.u.data.length;

  while (off + sizeof(struct iw_event) <= total)
    {
      ev = (struct iw_event *)(scan_buf + off);

      if (ev->len < sizeof(struct iw_event) || off + ev->len > total)
        {
          break;
        }

      switch (ev->cmd)
        {
          case SIOCGIWAP:
            /* A new AP starts here. */

            if (cur != NULL)
              {
                found++;
              }

            if (found >= max_aps)
              {
                cur = NULL;
                break;
              }

            cur = &aps[found];
            snprintf(cur->bssid, sizeof(cur->bssid),
                     "%02x:%02x:%02x:%02x:%02x:%02x",
                     (uint8_t)ev->u.ap_addr.sa_data[0],
                     (uint8_t)ev->u.ap_addr.sa_data[1],
                     (uint8_t)ev->u.ap_addr.sa_data[2],
                     (uint8_t)ev->u.ap_addr.sa_data[3],
                     (uint8_t)ev->u.ap_addr.sa_data[4],
                     (uint8_t)ev->u.ap_addr.sa_data[5]);
            break;

          case SIOCGIWESSID:
            if (cur != NULL)
              {
                const char *ssid = dm_wifi_event_ssid(ev, scan_buf, total);
                size_t len = ev->u.essid.length;

                if (ssid != NULL)
                  {
                    if (len >= sizeof(cur->ssid))
                      {
                        len = sizeof(cur->ssid) - 1;
                      }

                    memcpy(cur->ssid, ssid, len);
                    cur->ssid[len] = '\0';
                  }
              }
            break;

          case IWEVQUAL:
            if (cur != NULL)
              {
                cur->rssi = (int)(int8_t)ev->u.qual.level;
              }
            break;

          case SIOCGIWFREQ:
            if (cur != NULL)
              {
                /* wifi_sim reports MHz * 10; other drivers report MHz. */

                int m = ev->u.freq.m;

                cur->freq = m > 100000 ? m / 10 : m;
              }
            break;

          case SIOCGIWENCODE:
            if (cur != NULL)
              {
                cur->secure = (ev->u.data.flags & IW_ENCODE_DISABLED) == 0 &&
                              ev->u.data.length > 0;
              }
            break;

          default:
            break;
        }

      off += ev->len;
    }

  if (cur != NULL)
    {
      found++;
    }

  /* Drop entries we could not name. */

  {
    int out = 0;

    for (int i = 0; i < found && i < max_aps; i++)
      {
        if (aps[i].ssid[0] != '\0')
          {
            if (out != i)
              {
                aps[out] = aps[i];
              }

            out++;
          }
      }

    found = out;
  }

  DM_LOG("wifi: scan found %d AP(s) on %s", found, ifname);
  return found;
#else
  (void)aps;
  (void)max_aps;
  return -ENODEV;
#endif
}

int dm_net_wifi_connect(const char *ssid, const char *psk)
{
#ifdef DM_HAVE_WAPI
  const char *ifname = dm_net_wifi_ifname();
  struct iwreq iwr;
  int ret;

  if (ifname == NULL || ssid == NULL || ssid[0] == '\0')
    {
      return -ENODEV;
    }

  if (dm_net_socket() < 0)
    {
      return -EIO;
    }

  if (psk != NULL && psk[0] != '\0')
    {
      static struct iw_encode_ext ext;

      memset(&ext, 0, sizeof(ext));
      ext.alg     = IW_ENCODE_ALG_CCMP;
      ext.key_len = strlen(psk);

      if (ext.key_len > sizeof(ext.key))
        {
          ext.key_len = sizeof(ext.key);
        }

      memcpy(ext.key, psk, ext.key_len);

      memset(&iwr, 0, sizeof(iwr));
      strlcpy(iwr.ifr_name, ifname, IFNAMSIZ);
      iwr.u.encoding.pointer = &ext;
      iwr.u.encoding.length  = sizeof(ext);
      iwr.u.encoding.flags   = IW_ENCODE_INDEX;

      ret = ioctl(g_sock, SIOCSIWENCODEEXT, (unsigned long)&iwr);
      if (ret < 0)
        {
          DM_WARN("wifi: setting the passphrase failed (%d)", errno);
        }
    }

  memset(&iwr, 0, sizeof(iwr));
  strlcpy(iwr.ifr_name, ifname, IFNAMSIZ);
  iwr.u.essid.pointer = (void *)ssid;
  iwr.u.essid.length  = strlen(ssid);
  iwr.u.essid.flags   = 1;

  if (ioctl(g_sock, SIOCSIWESSID, (unsigned long)&iwr) < 0)
    {
      DM_ERR("wifi: SIOCSIWESSID(%s) failed: %d", ssid, errno);
      return -errno;
    }

  DM_LOG("wifi: association requested for '%s'", ssid);
  return 0;
#else
  (void)ssid;
  (void)psk;
  return -ENODEV;
#endif
}

int dm_net_wifi_disconnect(void)
{
#ifdef DM_HAVE_WAPI
  const char *ifname = dm_net_wifi_ifname();
  struct iwreq iwr;

  if (ifname == NULL || dm_net_socket() < 0)
    {
      return -ENODEV;
    }

  memset(&iwr, 0, sizeof(iwr));
  strlcpy(iwr.ifr_name, ifname, IFNAMSIZ);
  iwr.u.essid.pointer = (void *)"";
  iwr.u.essid.length  = 0;
  iwr.u.essid.flags   = 0;

  if (ioctl(g_sock, SIOCSIWESSID, (unsigned long)&iwr) < 0)
    {
      return -errno;
    }

  return 0;
#else
  return -ENODEV;
#endif
}

int dm_net_describe(char *buf, size_t len)
{
  size_t used = 0;
  int i;

  if (buf == NULL || len == 0)
    {
      return -EINVAL;
    }

  buf[0] = '\0';

  if (!g_refreshed)
    {
      snprintf(buf, len, "not refreshed");
      return 0;
    }

  if (g_status.count == 0)
    {
      snprintf(buf, len, "no interfaces");
      return 0;
    }

  for (i = 0; i < g_status.count; i++)
    {
      const struct dm_net_if_s *e = &g_status.ifs[i];
      int n;

      n = snprintf(buf + used, used < len ? len - used : 0, "%s%s %s%s%s",
                   i > 0 ? "; " : "", e->name,
                   e->up ? (e->running ? "UP" : "up") : "down",
                   e->ip[0] != '\0' ? " " : "", e->ip);

      if (n < 0)
        {
          break;
        }

      used += (size_t)n;

      if (used >= len)
        {
          break;
        }
    }

  return 0;
}

/****************************************************************************
 * apps/examples/deskmate/src/hal/dm_camera.h
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * Camera half of the DeskMate HAL.
 *
 * Two backends behind one call:
 *
 *   v4l2      : /dev/video0 through the V4L2 capture interface, which is what
 *               the ESP32-P4 board exposes (SC2336 -> MIPI-CSI -> V4L2).  The
 *               sensor delivers RAW8 (SBGGR8); the preview does a 2x2 quad
 *               demosaic so a colour thumbnail comes out at half resolution
 *               without an ISP or a heavy scaler.  If the driver can hand out
 *               RGB565 directly, that path is used unchanged.
 *
 *   synthetic : a moving pattern generated on the fly.  This is what the
 *               simulator uses (there is no /dev/video0 on a headless CI
 *               host) and what the UI falls back to when the sensor is
 *               missing, so the camera page and the event engine can always be
 *               exercised end to end.
 *
 * Frames are RGB565, already sized for the preview canvas.
 ****************************************************************************/

#ifndef __APPS_EXAMPLES_DESKMATE_HAL_DM_CAMERA_H
#define __APPS_EXAMPLES_DESKMATE_HAL_DM_CAMERA_H

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <stdbool.h>
#include <stdint.h>

/****************************************************************************
 * Public Types
 ****************************************************************************/

struct dm_camera_frame_s
{
  const uint16_t *pixels;   /* RGB565 preview, width*height */
  int  width;
  int  height;
  int  seq;                 /* Frame counter since start */
  bool synthetic;           /* true: generated pattern, not a real sensor */
};

/****************************************************************************
 * Public Function Prototypes
 ****************************************************************************/

/* Probe the camera and set up the capture pipeline.  preview_w/h is the size
 * the UI wants.  Returns 0 when *some* backend is ready (possibly synthetic).
 */

int dm_camera_create(int preview_w, int preview_h);

/* Backend actually in use: "v4l2" or "synthetic". */

const char *dm_camera_backend(void);

bool dm_camera_ready(void);

/* Fetch the newest frame.  Returns 0 when a frame was produced, -EAGAIN when
 * nothing new is available this iteration.
 */

int dm_camera_poll(struct dm_camera_frame_s *out);

/* Push the last frame through the same path without new capture (used after a
 * page rebuild, so the canvas always has something to show).
 */

const struct dm_camera_frame_s *dm_camera_last(void);

void dm_camera_destroy(void);

#endif /* __APPS_EXAMPLES_DESKMATE_HAL_DM_CAMERA_H */

/****************************************************************************
 * apps/examples/deskmate/src/hal/dm_camera.c
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * Camera half of the DeskMate HAL: see dm_camera.h.
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <fcntl.h>
#include <poll.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <unistd.h>

#if defined(CONFIG_VIDEO) && defined(CONFIG_VIDEO_STREAM)
#  include <nuttx/video/video.h>
#  include <nuttx/video/v4l2_cap.h>
#  define DM_HAVE_V4L2 1
#endif

#include <time.h>

#include "dm_config.h"
#include "dm_log.h"
#include "hal/dm_camera.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#ifdef CONFIG_EXAMPLES_DESKMATE_CAMERA_DEVPATH
#  define DM_CAMERA_PATH CONFIG_EXAMPLES_DESKMATE_CAMERA_DEVPATH
#else
#  define DM_CAMERA_PATH "/dev/video0"
#endif

#define DM_CAMERA_BUFFERS 3

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct dm_camera_buf_s
{
  void   *mem;
  size_t  len;
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static int   g_fd = -1;
static bool  g_ready;
static bool  g_synthetic = true;
static int   g_width;
static int   g_height;
static int   g_src_width;
static int   g_src_height;
static uint32_t g_src_format;
static int   g_seq;

static struct dm_camera_buf_s g_bufs[DM_CAMERA_BUFFERS];
static int g_nbufs;
static bool g_streaming;

static struct dm_camera_frame_s g_frame;
static uint16_t *g_pixels;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

#ifdef DM_HAVE_V4L2
static int dm_camera_try_fmt(uint32_t pixfmt)
{
  struct v4l2_format fmt;

  memset(&fmt, 0, sizeof(fmt));
  fmt.type                = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  fmt.fmt.pix.width       = g_src_width;
  fmt.fmt.pix.height      = g_src_height;
  fmt.fmt.pix.pixelformat = pixfmt;
  fmt.fmt.pix.field       = V4L2_FIELD_ANY;

  if (ioctl(g_fd, VIDIOC_S_FMT, (unsigned long)&fmt) < 0)
    {
      return -errno;
    }

  g_src_width  = fmt.fmt.pix.width;
  g_src_height = fmt.fmt.pix.height;
  g_src_format = fmt.fmt.pix.pixelformat;

  return 0;
}
#endif

/* 2x2 quad demosaic of a BGGR RAW8 frame, resampled straight into the preview
 * buffer.  Averaging each quad gives one RGB pixel, so the preview is half the
 * sensor resolution; the scale factor then maps that onto the canvas.
 */

static void dm_camera_convert_bayer(const uint8_t *src, int sw, int sh,
                                    uint16_t *dst, int dw, int dh)
{
  int qw = sw / 2;
  int qh = sh / 2;

  if (qw <= 0 || qh <= 0)
    {
      return;
    }

  for (int y = 0; y < dh; y++)
    {
      int sy = (y * qh) / dh;
      const uint8_t *row0 = src + (size_t)(sy * 2) * sw;
      const uint8_t *row1 = row0 + sw;
      uint16_t *out = dst + (size_t)y * dw;

      for (int x = 0; x < dw; x++)
        {
          int sx = (x * qw) / dw;
          const uint8_t *q0 = row0 + sx * 2;
          const uint8_t *q1 = row1 + sx * 2;

          /* BGGR: (0,0)=B (0,1)=G / (1,0)=G (1,1)=R */

          int b = q0[0];
          int g = (q0[1] + q1[0]) / 2;
          int r = q1[1];

          out[x] = (uint16_t)(((r & 0xf8) << 8) | ((g & 0xfc) << 3) |
                              ((b & 0xf8) >> 3));
        }
    }
}

/* RGB565 (or RGB888) source -> RGB565 preview. */

static void dm_camera_convert_rgb(const uint8_t *src, int sw, int sh,
                                  uint16_t *dst, int dw, int dh)
{
  for (int y = 0; y < dh; y++)
    {
      int sy = (y * sh) / dh;
      uint16_t *out = dst + (size_t)y * dw;

      for (int x = 0; x < dw; x++)
        {
          int sx = (x * sw) / dw;

          if (g_src_format == V4L2_PIX_FMT_RGB565)
            {
              out[x] = ((const uint16_t *)src)[(size_t)sy * sw + sx];
            }
          else
            {
              const uint8_t *p = src + ((size_t)sy * sw + sx) * 3;
              out[x] = (uint16_t)(((p[0] & 0xf8) << 8) |
                                  ((p[1] & 0xfc) << 3) | ((p[2] & 0xf8) >> 3));
            }
        }
    }
}

/* Synthetic pattern: a colour ramp plus a moving block, so the preview is
 * obviously "live" and its motion can drive the proactive engine.
 */

static void dm_camera_synth(uint16_t *dst, int dw, int dh, int seq)
{
  int bx = (seq * 7) % (dw > 40 ? dw - 40 : 1);
  int by = (dh > 40) ? (dh - 40) / 2 + (seq % 20) : 0;

  for (int y = 0; y < dh; y++)
    {
      uint16_t *out = dst + (size_t)y * dw;

      for (int x = 0; x < dw; x++)
        {
          int r = (x * 255) / (dw > 0 ? dw : 1);
          int g = (y * 255) / (dh > 0 ? dh : 1);
          int b = ((x + y + seq) * 3) & 0xff;

          if (x >= bx && x < bx + 40 && y >= by && y < by + 40)
            {
              r = 240;
              g = 200;
              b = 40;
            }

          out[x] = (uint16_t)(((r & 0xf8) << 8) | ((g & 0xfc) << 3) |
                              ((b & 0xf8) >> 3));
        }
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int dm_camera_create(int preview_w, int preview_h)
{
  if (g_ready)
    {
      return 0;
    }

  if (preview_w <= 0 || preview_h <= 0)
    {
      return -EINVAL;
    }

  g_width  = preview_w;
  g_height = preview_h;

  g_pixels = malloc((size_t)preview_w * preview_h * sizeof(uint16_t));
  if (g_pixels == NULL)
    {
      DM_ERR("camera: no memory for a %dx%d preview", preview_w, preview_h);
      return -ENOMEM;
    }

  memset(g_pixels, 0, (size_t)preview_w * preview_h * sizeof(uint16_t));

#ifdef DM_HAVE_V4L2
  g_fd = open(DM_CAMERA_PATH, O_RDWR);
  if (g_fd >= 0)
    {
      g_src_width  = 1280;
      g_src_height = 720;

      if (dm_camera_try_fmt(V4L2_PIX_FMT_RGB565) == 0 ||
          dm_camera_try_fmt(V4L2_PIX_FMT_SBGGR8) == 0 ||
          dm_camera_try_fmt(V4L2_PIX_FMT_RGB24) == 0)
        {
          struct v4l2_requestbuffers req;
          int i;

          memset(&req, 0, sizeof(req));
          req.count  = DM_CAMERA_BUFFERS;
          req.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
          req.memory = V4L2_MEMORY_USERPTR;

          if (ioctl(g_fd, VIDIOC_REQBUFS, (unsigned long)&req) == 0)
            {
              size_t bytes = (size_t)g_src_width * g_src_height *
                             (g_src_format == V4L2_PIX_FMT_RGB565 ? 2 :
                              g_src_format == V4L2_PIX_FMT_RGB24 ? 3 : 1);

              for (i = 0; i < DM_CAMERA_BUFFERS && i < (int)req.count; i++)
                {
                  struct v4l2_buffer buf;

                  g_bufs[i].mem = malloc(bytes);
                  g_bufs[i].len = bytes;

                  if (g_bufs[i].mem == NULL)
                    {
                      break;
                    }

                  memset(&buf, 0, sizeof(buf));
                  buf.type      = V4L2_BUF_TYPE_VIDEO_CAPTURE;
                  buf.memory    = V4L2_MEMORY_USERPTR;
                  buf.index     = i;
                  buf.m.userptr = (unsigned long)g_bufs[i].mem;
                  buf.length    = bytes;

                  if (ioctl(g_fd, VIDIOC_QBUF, (unsigned long)&buf) < 0)
                    {
                      DM_WARN("camera: QBUF %d failed: %d", i, errno);
                      free(g_bufs[i].mem);
                      g_bufs[i].mem = NULL;
                      break;
                    }
                }

              g_nbufs = i;

              if (g_nbufs > 0)
                {
                  enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

                  if (ioctl(g_fd, VIDIOC_STREAMON, (unsigned long)&type) == 0)
                    {
                      g_streaming  = true;
                      g_synthetic  = false;
                      g_ready      = true;

                      DM_LOG("camera: v4l2 %dx%d fmt=0x%08x -> preview %dx%d",
                             g_src_width, g_src_height,
                             (unsigned)g_src_format, g_width, g_height);
                      return 0;
                    }

                  DM_ERR("camera: STREAMON failed: %d", errno);
                }
            }
          else
            {
              DM_WARN("camera: REQBUFS failed: %d", errno);
            }
        }
      else
        {
          DM_WARN("camera: no supported pixel format on %s", DM_CAMERA_PATH);
        }

      close(g_fd);
      g_fd = -1;
    }
  else
    {
      DM_LOG("camera: %s not available (%d), using the synthetic source",
             DM_CAMERA_PATH, errno);
    }
#endif

  g_synthetic = true;
  g_ready = true;

  DM_LOG("camera: synthetic %dx%d source", g_width, g_height);
  return 0;
}

const char *dm_camera_backend(void)
{
  return g_synthetic ? "synthetic" : "v4l2";
}

bool dm_camera_ready(void)
{
  return g_ready;
}

int dm_camera_poll(struct dm_camera_frame_s *out)
{
  if (!g_ready)
    {
      return -ENODEV;
    }

  if (g_synthetic)
    {
      dm_camera_synth(g_pixels, g_width, g_height, g_seq++);
    }
  else
    {
#ifdef DM_HAVE_V4L2
      struct v4l2_buffer buf;
      struct pollfd pfd;
      int ret;

      pfd.fd     = g_fd;
      pfd.events = POLLIN;

      ret = poll(&pfd, 1, 0);
      if (ret <= 0)
        {
          return -EAGAIN;
        }

      memset(&buf, 0, sizeof(buf));
      buf.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
      buf.memory = V4L2_MEMORY_USERPTR;

      if (ioctl(g_fd, VIDIOC_DQBUF, (unsigned long)&buf) < 0)
        {
          return -EAGAIN;
        }

      if (buf.index < (unsigned)DM_CAMERA_BUFFERS && g_bufs[buf.index].mem)
        {
          const uint8_t *src = g_bufs[buf.index].mem;

          if (g_src_format == V4L2_PIX_FMT_SBGGR8)
            {
              dm_camera_convert_bayer(src, g_src_width, g_src_height,
                                      g_pixels, g_width, g_height);
            }
          else
            {
              dm_camera_convert_rgb(src, g_src_width, g_src_height,
                                    g_pixels, g_width, g_height);
            }
        }

      (void)ioctl(g_fd, VIDIOC_QBUF, (unsigned long)&buf);
#endif
    }

  g_seq++;

  g_frame.pixels    = g_pixels;
  g_frame.width     = g_width;
  g_frame.height    = g_height;
  g_frame.seq       = g_seq;
  g_frame.synthetic = g_synthetic;

  if (out != NULL)
    {
      *out = g_frame;
    }

  return 0;
}

const struct dm_camera_frame_s *dm_camera_last(void)
{
  return g_ready ? &g_frame : NULL;
}

void dm_camera_destroy(void)
{
#ifdef DM_HAVE_V4L2
  if (g_fd >= 0 && g_streaming)
    {
      enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

      (void)ioctl(g_fd, VIDIOC_STREAMOFF, (unsigned long)&type);
    }

  for (int i = 0; i < DM_CAMERA_BUFFERS; i++)
    {
      if (g_bufs[i].mem != NULL)
        {
          free(g_bufs[i].mem);
          g_bufs[i].mem = NULL;
        }
    }

  if (g_fd >= 0)
    {
      close(g_fd);
      g_fd = -1;
    }
#endif

  if (g_pixels != NULL)
    {
      free(g_pixels);
      g_pixels = NULL;
    }

  g_ready = false;
  g_streaming = false;
}

