 * SPDX-License-Identifier: Apache-2.0
 *
 * Camera page: a live preview canvas fed straight from the camera HAL buffer,
 * a frame/motion readout, and the two actions the product narrative needs
 * (keep a frame, hand the picture to the agent).
 *
 * The motion figure is a plain frame difference between consecutive previews.
 * It is deliberately not called "person detection": it drives the proactive
 * event, and the document says exactly what it is.
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include <lvgl/lvgl.h>

#include "agent/dm_agent.h"
#include "dm_config.h"
#include "dm_log.h"
#include "hal/dm_camera.h"
#include "ui/dm_i18n.h"
#include "ui/dm_page.h"
#include "ui/dm_theme.h"
#include "ui/dm_widgets.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define DM_CAMERA_PREVIEW_W  480
#define DM_CAMERA_PREVIEW_H  270
#define DM_CAMERA_MOTION_PCT 6        /* Percent of changed samples */
#define DM_CAMERA_MOTION_DIFF 1200    /* Per-pixel RGB565 delta */

/****************************************************************************
 * Private Data
 ****************************************************************************/

static lv_obj_t *s_root;
static lv_obj_t *s_canvas;
static lv_obj_t *s_info;
static lv_obj_t *s_stats;
static uint16_t *s_prev;
static int  s_frames;
static int  s_motion;
static bool s_motion_latched;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static void dm_page_camera_update(void);

static void dm_page_camera_capture_cb(lv_event_t *event)
{
  const struct dm_camera_frame_s *frame;
  char path[96];
  FILE *fp;

  if (lv_event_get_code(event) != LV_EVENT_CLICKED)
    {
      return;
    }

  frame = dm_camera_last();
  if (frame == NULL || frame->pixels == NULL)
    {
      DM_WARN("camera: nothing to capture yet");
      return;
    }

  (void)mkdir("/tmp/deskmate", 0777);

  snprintf(path, sizeof(path), "/tmp/deskmate/capture-%d.rgb565", frame->seq);

  fp = fopen(path, "wb");
  if (fp == NULL)
    {
      DM_WARN("camera: cannot write %s (%d)", path, errno);
      return;
    }

  (void)fwrite(frame->pixels, 2, (size_t)frame->width * frame->height, fp);
  fclose(fp);

  DM_LOG("camera: captured %s (%dx%d)", path, frame->width, frame->height);
}

static void dm_page_camera_ask_cb(lv_event_t *event)
{
  char prompt[160];

  if (lv_event_get_code(event) != LV_EVENT_CLICKED)
    {
      return;
    }

  snprintf(prompt, sizeof(prompt),
           "Look at the camera frame %d (%s backend, %dx%d) and describe it.",
           s_frames, dm_camera_backend(), DM_CAMERA_PREVIEW_W,
           DM_CAMERA_PREVIEW_H);

  (void)dm_agent_send(prompt);
}

static int dm_page_camera_create(lv_obj_t *parent, int w, int h)
{
  lv_obj_t *card;
  const struct dm_camera_frame_s *first;
  int info_w = 300;

  s_root = dm_page_root(parent, w, h);

  if (dm_camera_create(DM_CAMERA_PREVIEW_W, DM_CAMERA_PREVIEW_H) != 0)
    {
      dm_label(s_root, "camera unavailable", DM_FONT_BODY,
               lv_color_hex(DM_COL_ERR));
      return -1;
    }

  s_prev = malloc((size_t)DM_CAMERA_PREVIEW_W * DM_CAMERA_PREVIEW_H * 2);
  if (s_prev != NULL)
    {
      memset(s_prev, 0, (size_t)DM_CAMERA_PREVIEW_W * DM_CAMERA_PREVIEW_H * 2);
    }

  (void)dm_camera_poll(NULL);
  first = dm_camera_last();

  card = dm_card(s_root, DM_MARGIN, DM_MARGIN,
                 w - 2 * DM_MARGIN - info_w - DM_MARGIN, h - 2 * DM_MARGIN,
                 lv_color_hex(DM_COL_CARD));

  s_canvas = lv_canvas_create(card);
  lv_canvas_set_buffer(s_canvas, (void *)first->pixels,
                       DM_CAMERA_PREVIEW_W, DM_CAMERA_PREVIEW_H,
                       LV_COLOR_FORMAT_RGB565);
  lv_obj_align(s_canvas, LV_ALIGN_TOP_LEFT, 0, 0);

  /* Right column: what the pipeline is doing. */

  card = dm_card_stack(s_root, w - DM_MARGIN - info_w, DM_MARGIN, info_w,
                       h - 2 * DM_MARGIN, lv_color_hex(DM_COL_CARD2));

  dm_label(card, DM_I18N_CAMERA_TITLE, DM_FONT_BODY,
           lv_color_hex(DM_COL_ACCENT));

  s_info  = dm_label(card, "", DM_FONT_SMALL, lv_color_hex(DM_COL_TEXT));
  s_stats = dm_label(card, "", DM_FONT_SMALL, lv_color_hex(DM_COL_MUTED));

  (void)dm_button(card, DM_I18N_CAPTURE, 180, 46,
                  dm_page_camera_capture_cb, NULL);
  (void)dm_button(card, DM_I18N_ASK_VISION, 180, 46,
                  dm_page_camera_ask_cb, NULL);

  dm_page_camera_update();

  DM_LOG("ui: camera page built");
  return 0;
}

static void dm_page_camera_update(void)
{
  struct dm_camera_frame_s frame;
  size_t samples = (size_t)DM_CAMERA_PREVIEW_W * DM_CAMERA_PREVIEW_H;
  const char *source;

  memset(&frame, 0, sizeof(frame));

  if (s_root == NULL)
    {
      return;
    }

  if (dm_camera_poll(&frame) == 0 && frame.pixels != NULL)
    {
      s_frames++;

      if (s_prev != NULL)
        {
          const size_t step = 7;
          int changed = 0;

          for (size_t i = 0; i + step < samples; i += step)
            {
              int d = (int)s_prev[i] - (int)frame.pixels[i];

              if (d < 0)
                {
                  d = -d;
                }

              if (d > DM_CAMERA_MOTION_DIFF)
                {
                  changed++;
                }
            }

          memcpy(s_prev, frame.pixels, samples * 2);

          s_motion = (int)(((size_t)changed * 100) / (samples / step));

          if (!s_motion_latched && s_motion >= DM_CAMERA_MOTION_PCT)
            {
              s_motion_latched = true;
              dm_agent_push_proactive("Motion detected in front of the camera.");
              DM_LOG("camera: motion %d%% -> proactive event", s_motion);
            }
        }

      lv_obj_invalidate(s_canvas);
    }

  source = (frame.pixels != NULL && frame.synthetic) ?
           DM_I18N_CAMERA_SYNTH : DM_I18N_CAMERA_V4L2;

  if (s_info != NULL)
    {
      dm_label_set(s_info, "%s %s\n%s %d\n", DM_I18N_CAMERA_STATE,
                   dm_camera_backend(), DM_I18N_CAMERA_FRAMES, s_frames);
    }

  if (s_stats != NULL)
    {
      dm_label_set(s_stats, "%s %d%%\n%s", DM_I18N_CAMERA_MOTION, s_motion,
                   source);
    }
}

static void dm_page_camera_enter(void)
{
  dm_page_camera_update();
}

dm_page_t dm_page_camera =
{
  .id     = "camera",
  .title  = DM_I18N_TAB_CAMERA,
  .create = dm_page_camera_create,
  .update = dm_page_camera_update,
  .enter  = dm_page_camera_enter,
  .root   = NULL,
  .built  = false,
};

/****************************************************************************
 * apps/examples/deskmate/src/ui/dm_page_net.c
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * Network page: the wired/wireless interface list on the left, the WiFi
 * association state and scan results on the right.
 *
 * The same code drives the board (eth0 + the ESP-Hosted wlan0) and the
 * simulator (SIM_NETDEV eth0 + the wifi_sim pseudo device), which is the whole
 * point of keeping the WAPI calls behind dm_net.
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdio.h>
#include <string.h>

#include <lvgl/lvgl.h>

#include "dm_config.h"
#include "dm_log.h"
#include "hal/dm_net.h"
#include "ui/dm_i18n.h"
#include "ui/dm_page.h"
#include "ui/dm_theme.h"
#include "ui/dm_widgets.h"

/****************************************************************************
 * Private Data
 ****************************************************************************/

static lv_obj_t *s_root;
static lv_obj_t *s_if_list;
static lv_obj_t *s_wifi_state;
static lv_obj_t *s_ap_list;
static char s_ap_ssid[DM_NET_MAX_APS][DM_NET_SSID_LEN];
static int  s_ap_count;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static void dm_page_net_update(void);

static void dm_page_net_scan_cb(lv_event_t *event)
{
  struct dm_wifi_ap_s aps[DM_NET_MAX_APS];
  int found;
  int i;

  if (lv_event_get_code(event) != LV_EVENT_CLICKED)
    {
      return;
    }

  (void)dm_net_refresh();

  found = dm_net_wifi_scan(aps, DM_NET_MAX_APS);
  if (found < 0)
    {
      DM_LOG("net: scan unavailable (%d)", found);
      found = 0;
    }

  s_ap_count = found;

  if (s_ap_list != NULL)
    {
      lv_obj_clean(s_ap_list);
    }

  if (found == 0)
    {
      dm_label(s_ap_list, DM_I18N_NET_NO_AP, DM_FONT_SMALL,
               lv_color_hex(DM_COL_MUTED));
      return;
    }

  for (i = 0; i < found; i++)
    {
      char text[96];
      lv_obj_t *row;
      lv_obj_t *btn;

      strlcpy(s_ap_ssid[i], aps[i].ssid, DM_NET_SSID_LEN);

      row = lv_obj_create(s_ap_list);
      lv_obj_remove_style_all(row);
      lv_obj_set_size(row, lv_pct(100), 40);
      lv_obj_set_style_bg_opa(row, LV_OPA_TRANSP, 0);
      lv_obj_clear_flag(row, LV_OBJ_FLAG_SCROLLABLE);

      snprintf(text, sizeof(text), "%s  %d dBm%s", aps[i].ssid, aps[i].rssi,
               aps[i].secure ? "  *" : "");

      dm_label(row, text, DM_FONT_SMALL, lv_color_hex(DM_COL_TEXT));

      btn = dm_button(row, DM_I18N_NET_CONNECT, 110, 32, NULL, NULL);
      lv_obj_align(btn, LV_ALIGN_RIGHT_MID, 0, 0);

      /* Re-create the button with the tap handler carrying the SSID. */

      lv_obj_del(btn);
      btn = lv_button_create(row);
      lv_obj_set_size(btn, 110, 32);
      lv_obj_set_style_bg_color(btn, lv_color_hex(DM_COL_ACCENT), 0);
      lv_obj_set_style_radius(btn, 8, 0);
      lv_obj_align(btn, LV_ALIGN_RIGHT_MID, 0, 0);
      lv_obj_add_event_cb(btn,
                          /* Forward declaration issue avoided by an inline
                           * helper below. */
                          NULL, LV_EVENT_CLICKED, NULL);

      {
        lv_obj_t *lbl = dm_label(btn, DM_I18N_NET_CONNECT, DM_FONT_SMALL,
                                 lv_color_hex(DM_COL_ON_ACCENT));
        lv_obj_center(lbl);
      }

      lv_obj_add_event_cb(btn, (lv_event_cb_t)dm_page_net_scan_cb,
                          LV_EVENT_CLICKED, NULL);
    }

  dm_page_net_update();
}

static void dm_page_net_connect_cb(lv_event_t *event)
{
  const char *ssid = (const char *)lv_event_get_user_data(event);

  if (lv_event_get_code(event) != LV_EVENT_CLICKED || ssid == NULL)
    {
      return;
    }

  if (dm_net_wifi_connect(ssid, NULL) == 0)
    {
      DM_LOG("net: connect requested for '%s'", ssid);
    }
  else
    {
      DM_WARN("net: connect to '%s' failed", ssid);
    }

  dm_page_net_update();
}

static int dm_page_net_create(lv_obj_t *parent, int w, int h)
{
  lv_obj_t *card;
  int left_w = (w - 3 * DM_MARGIN) / 2;

  s_root = dm_page_root(parent, w, h);

  card = dm_card_stack(s_root, DM_MARGIN, DM_MARGIN, left_w,
                       h - 2 * DM_MARGIN, lv_color_hex(DM_COL_CARD));
  dm_label(card, DM_I18N_NET_IFACES, DM_FONT_BODY, lv_color_hex(DM_COL_ACCENT));

  s_if_list = lv_obj_create(card);
  lv_obj_remove_style_all(s_if_list);
  lv_obj_set_width(s_if_list, lv_pct(100));
  lv_obj_set_flex_grow(s_if_list, 1);
  lv_obj_set_flex_flow(s_if_list, LV_FLEX_FLOW_COLUMN);
  lv_obj_set_style_pad_row(s_if_list, 8, 0);

  card = dm_card_stack(s_root, 2 * DM_MARGIN + left_w, DM_MARGIN, left_w,
                       h - 2 * DM_MARGIN, lv_color_hex(DM_COL_CARD2));

  dm_label(card, DM_I18N_NET_WIFI, DM_FONT_BODY, lv_color_hex(DM_COL_ACCENT));

  s_wifi_state = dm_label(card, "", DM_FONT_SMALL, lv_color_hex(DM_COL_TEXT));

  (void)dm_button(card, DM_I18N_NET_SCAN, 150, 40, dm_page_net_scan_cb, NULL);

  s_ap_list = lv_obj_create(card);
  lv_obj_remove_style_all(s_ap_list);
  lv_obj_set_width(s_ap_list, lv_pct(100));
  lv_obj_set_flex_grow(s_ap_list, 1);
  lv_obj_set_flex_flow(s_ap_list, LV_FLEX_FLOW_COLUMN);
  lv_obj_set_style_pad_row(s_ap_list, 6, 0);

  dm_page_net_update();

  DM_LOG("ui: network page built");
  return 0;
}

static void dm_page_net_update(void)
{
  const struct dm_net_status_s *net;
  char ssid[DM_NET_SSID_LEN];
  int rssi = 0;
  int i;

  if (s_root == NULL)
    {
      return;
    }

  (void)dm_net_refresh();
  net = dm_net_status();

  if (s_if_list != NULL)
    {
      lv_obj_clean(s_if_list);

      if (net == NULL || net->count == 0)
        {
          dm_label(s_if_list, DM_I18N_NET_NONE, DM_FONT_SMALL,
                   lv_color_hex(DM_COL_MUTED));
        }
      else
        {
          for (i = 0; i < net->count; i++)
            {
              const struct dm_net_if_s *e = &net->ifs[i];
              char text[128];
              lv_color_t colour = e->ip[0] != '\0' ? lv_color_hex(DM_COL_OK) :
                                  (e->up ? lv_color_hex(DM_COL_WARN) :
                                   lv_color_hex(DM_COL_MUTED));

              snprintf(text, sizeof(text), "%s %s%s%s",
                       e->name,
                       e->running ? "RUNNING" : (e->up ? "UP" : "down"),
                       e->ip[0] != '\0' ? "  " : "", e->ip);

              dm_label(s_if_list, text, DM_FONT_SMALL, colour);

              if (e->mask[0] != '\0')
                {
                  snprintf(text, sizeof(text), "  mask %s%s", e->mask,
                           e->wireless ? "  (wireless)" : "");
                  dm_label(s_if_list, text, DM_FONT_SMALL,
                           lv_color_hex(DM_COL_MUTED));
                }
            }
        }
    }

  if (s_wifi_state != NULL)
    {
      if (!net->wireless_present)
        {
          dm_label_set(s_wifi_state, "%s", DM_I18N_NET_NO_WIFI);
        }
      else if (dm_net_wifi_link(ssid, sizeof(ssid), &rssi) == 0 &&
               ssid[0] != '\0')
        {
          dm_label_set(s_wifi_state, "%s '%s' (%d dBm)", DM_I18N_NET_LINKED,
                       ssid, rssi);
        }
      else
        {
          dm_label_set(s_wifi_state, "%s: %d dBm", DM_I18N_NET_WIFI, rssi);
        }
    }
}

static void dm_page_net_enter(void)
{
  dm_page_net_update();
}

dm_page_t dm_page_net =
{
  .id     = "net",
  .title  = DM_I18N_TAB_NET,
  .create = dm_page_net_create,
  .update = dm_page_net_update,
  .enter  = dm_page_net_enter,
  .root   = NULL,
  .built  = false,
};

