      lv_obj_delete(s_confirm_modal);
      s_confirm_modal = NULL;
    }

  /* 弹窗都建在 top layer 上的同一个容器里，清掉即可。 */

  lv_obj_clean(top);
  lv_obj_clear_flag(top, LV_OBJ_FLAG_CLICKABLE);
