  lv_keyboard_set_textarea(kb, ta);
  lv_obj_add_event_cb(kb, dm_modal_kb_cb, LV_EVENT_READY, ta);
  lv_obj_add_event_cb(kb, dm_modal_kb_cb, LV_EVENT_CANCEL, ta);
