      dm_label_set(s_wifi_state, "%s", DM_I18N_NET_SCANNING);
    }

  if (s_ap_list != NULL)
    {
      lv_obj_clean(s_ap_list);
      dm_label(s_ap_list, DM_I18N_NET_SCANNING, DM_FONT_SMALL,
               lv_color_hex(DM_COL_MUTED));
