     * Only continue reading while the device is actually reporting a contact.
     * The two kinds of NuttX touchscreen driver behave differently:
     *
     *   - an interrupt-driven driver keeps read() blocked until a real event
     *     arrives, so "a sample was available" already means "there is news";
     *   - a *polling* driver (the GT9xx on this board) returns a full-size
     *     touch_sample_s on every read, including npoints == 0 while nothing
     *     is touching the panel.
     *
     * Gating purely on "read() succeeded" therefore made continue_reading
     * permanently true with a polling driver, and lv_indev_read_timer_cb() --
     * which loops on `do { read_cb() } while(data.continue_reading)` -- never
     * returned.  Since that timer runs before the display refresh timer inside
     * lv_timer_handler(), the screen was never refreshed at all: LVGL
     * initialised, created the demo, then sat inside the input timer forever
     * (measured: flush_cb never entered, framebuffer stayed at the boot test
     * colour, CPU idle between I2C transfers, and a trace showed
     * lv_indev_read_timer_cb as the only timer callback ever executed).
     *
     * A zero-point sample still yields a correctly released state, so dropping
     * it is safe; the indev timer polls again 33 ms later.
     */

    if(touchscreen_read_sample(touchscreen) && touchscreen->sample->npoints > 0) {
        /* Save last sample and let lvgl continue reading */
        lv_memcpy(touchscreen->last_sample, touchscreen->sample,
                  SIZEOF_TOUCH_SAMPLE_S(touchscreen->maxpoint));
        touchscreen->has_last_sample = true;
        data->continue_reading = true;
    }
    else {
        /* No more sample available, clear last sample flag */
        touchscreen->has_last_sample = false;
    }

#if LV_USE_GESTURE_RECOGNITION
    if(touchscreen->active_points > 1) {
        return;
    }
#endif
    data->state = touchscreen->last_state;
"}]

