s = s.replace('#include <nuttx/mutex.h>', '#include <nuttx/mutex.h>', 1)
old = '''  /* Begin Mutex: Lock to prevent concurrent reads */

  ret = nxmutex_lock(&priv->devlock);
  if (ret < 0)
    {
      return ret;
    }'''
new = '''  /* 不要用阻塞锁：驱动自己的中断/工作线程也会持有 devlock 做 I2C 传输，
   * 一旦 I2C 卡顿（重试/超时），调用方（LVGL 的输入读定时器）就会在这把锁上
   * 阻塞上秒 —— 真机实测单次 1539ms，表现为整屏卡顿。
   * 改成 trylock：锁忙就返回 -EAGAIN（等于"这次没有新样本"），下次轮询再读。
   */

  ret = nxmutex_trylock(&priv->devlock);
  if (ret < 0)
    {
      return -EAGAIN;
    }'''
assert old in s
s = s.replace(old, new, 1)
p.write_text(s); print('gt9xx_read: 阻塞锁 -> trylock')
