/* 硬件触摸读线程：把 I2C 读从 LVGL 的输入定时器里搬出来。
 * 背景（真机实测）：设备 indev 的 read(/dev/input0) 在 lv_timer_handler 内执行，
 * 而 I2C0 与相机 SCCB/ES8311 共用，单次读最坏 230~800ms ⇒ UI 一起卡。
 * 现在由本线程轮询，UI 只读"最新样本"（零阻塞）。
 */
static int  g_hw_fd = -1;
static volatile int g_hw_x, g_hw_y, g_hw_pressed, g_hw_have, g_hw_seq;
volatile uint32_t g_dbg_touch_hw_reads, g_dbg_touch_hw_us_max, g_dbg_touch_hw_us;

static void *dm_touch_hw_thread(void *arg)
{
  struct touch_sample_s sample;
  struct pollfd pfd;
  (void)arg;

  g_hw_fd = open(DM_INPUT_PATH, O_RDONLY | O_NONBLOCK);
  if (g_hw_fd < 0) { DM_ERR(...); return NULL; }
  pfd.fd = g_hw_fd; pfd.events = POLLIN;

  for (;;)
    {
      int rc = poll(&pfd, 1, 50);
      if (rc > 0 && (pfd.revents & POLLIN))
        {
          uint32_t t0 = (uint32_t)TICK2USEC(clock_systime_ticks());
          ssize_t n = read(g_hw_fd, &sample, sizeof(sample));
          uint32_t dt = (uint32_t)TICK2USEC(clock_systime_ticks()) - t0;
          g_dbg_touch_hw_reads++;
          g_dbg_touch_hw_us += dt;
          if (dt > g_dbg_touch_hw_us_max) g_dbg_touch_hw_us_max = dt;
          if (n == (ssize_t)sizeof(sample))
            {
              if (sample.npoints > 0)
                {
                  g_hw_x = sample.point[0].x; g_hw_y = sample.point[0].y;
                  g_hw_pressed = (sample.point[0].flags & TOUCH_DOWN) ? 1 : 0;
                }
              else g_hw_pressed = 0;
              g_hw_have = 1; g_hw_seq++;
            }
        }
    }
  return NULL;
}
